import type { Topic } from "@/lib/study/schema";

/**
 * OS depth topics, part B (Galvin chapters 9–13). Numbers from lib/study/os2.ts, checked by script:
 * 32-bit VA, 4 KB pages, 4-byte PTE: 2^20 entries, 4 MB table, 2 levels; 30-bit PA → 2^18 frames, inverted 1 MB.
 * 48-bit VA, 8-byte PTE: 4 levels of 9 bits. Buddy 1024: A70 → 128, B35 → 64, C80 → 128, internal 135; after −A, D60 → 64 at 192.
 * Clock on 1 2 3 4 1 2 5 1 2 3 4 5 (3 frames): 9 faults (FIFO 9, LRU 10); on 1 2 3 2 4 1 5 2: 7 faults.
 * COW, 10 pages, writes C3 P3 C7 C7 P1: 3 copies, 13 frames vs 20. Links: create a, ln a b, ln -s a s, rm a → b links 1, s dangling.
 * 1 GB disk, 4 KB blocks: 262,144 blocks, bit vector 32 KB = 8 blocks; 1000 free with grouping: 1 block.
 * 7200 rpm, seek 4 ms, 500 × 512 B per track, read 4 KB: rotation 4.17, transfer 0.133, total 8.3 ms. 6000 rpm, 100 sectors, read a track: 5 + 5 + 10 = 20 ms.
 * RAID with 4 × 2 TB: 0 → 8, 1 → 2, 5 → 6, 6 → 4, 10 → 4 TB. I/O 500 MHz, 2 MB/s, 4-byte units: polling 40%, interrupts 50%, DMA 0.15%.
 */
const OS = "/topics/operating-systems-os";

